/**
 * Learning Path CRUD actions.
 * @module     local_airpay_learningpath/path_actions
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 *
 * Two init paths:
 *   - init()       — for the index/list page
 *   - initView(id) — for the detail page (G-04)
 */
define("local_airpay_learningpath/path_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    // ── Path-level (index page) ────────────────────────────────────────

    var openPathForm = function(pathid, returnFocus) {
        var titleKey = (pathid === 0) ? "addpath" : "editpath";
        Str.get_string(titleKey, "local_airpay_learningpath").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_airpay_learningpath\\form\\edit_path",
                args: {pathid: pathid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || "Saved.";
                Notification.addNotification({message: message, type: "success"});
                window.location.reload();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var confirmStatus = function(pathid, name, makeActive, returnFocus) {
        var titleKey = makeActive ? "activatepath" : "archivepath";
        var msgKey = makeActive ? "confirmactivate" : "confirmarchive";
        Promise.all([
            Str.get_string(titleKey, "local_airpay_learningpath"),
            Str.get_string(msgKey, "local_airpay_learningpath", name),
            Str.get_string("pathstatuschanged", "local_airpay_learningpath")
        ]).then(function(strings) {
            var title = strings[0];
            var message = strings[1];
            var success = strings[2];
            Notification.confirm(title, message, title, null, function() {
                Ajax.call([{
                    methodname: "local_airpay_learningpath_toggle_status",
                    args: {pathid: pathid, active: makeActive}
                }])[0].then(function() {
                    Notification.addNotification({message: success, type: "success"});
                    window.location.reload();
                    return null;
                }).catch(Notification.exception);
            });
            if (returnFocus) setTimeout(function() { returnFocus.focus(); }, 100);
            return null;
        }).catch(Notification.exception);
    };

    var confirmDelete = function(pathid, name, returnFocus) {
        Promise.all([
            Str.get_string("deletepath", "local_airpay_learningpath"),
            Str.get_string("confirmdelete", "local_airpay_learningpath", name),
            Str.get_string("delete", "core"),
            Str.get_string("pathdeleted", "local_airpay_learningpath")
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], label = strings[2], success = strings[3];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{
                    methodname: "local_airpay_learningpath_delete_path",
                    args: {pathid: pathid}
                }])[0].then(function() {
                    Notification.addNotification({message: success, type: "success"});
                    window.location.reload();
                    return null;
                }).catch(Notification.exception);
                return true;
            }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    // ── Detail-page (G-04) ─────────────────────────────────────────────

    var refreshTable = function() {
        // Reload — simplest, avoids stale-cache issues across multiple datatables
        // on the same page. Cost is tiny on a detail page.
        window.location.reload();
    };

    var openAssignCoursesForm = function(pathid, returnFocus) {
        Str.get_string("add_courses", "local_airpay_learningpath").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_airpay_learningpath\\form\\assign_courses_form",
                args: {pathid: pathid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var detail = event.detail || {};
                var inserted = detail.inserted || 0;
                var message = inserted + " course" + (inserted === 1 ? "" : "s") + " added.";
                Notification.addNotification({message: message, type: "success"});
                refreshTable();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var openEnrolUsersForm = function(pathid, returnFocus) {
        Str.get_string("enrol_users", "local_airpay_learningpath").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_airpay_learningpath\\form\\enrol_users_form",
                args: {pathid: pathid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var detail = event.detail || {};
                var enrolled = detail.enrolled || 0;
                var message = enrolled + " user" + (enrolled === 1 ? "" : "s") + " enrolled.";
                Notification.addNotification({message: message, type: "success"});
                refreshTable();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var confirmUnassignCourse = function(pathid, courseid, name, returnFocus) {
        Promise.all([
            Str.get_string("add_courses", "local_airpay_learningpath"),
            Str.get_string("confirm_unassign_course", "local_airpay_learningpath", name),
            Str.get_string("delete", "core")
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], label = strings[2];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{
                    methodname: "local_airpay_learningpath_unassign_course",
                    args: {pathid: pathid, courseid: courseid}
                }])[0].then(function() {
                    Notification.addNotification({message: "Course removed from path.", type: "success"});
                    refreshTable();
                    return null;
                }).catch(Notification.exception);
                return true;
            }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    var confirmUnenrolUser = function(pathid, userid, name, returnFocus) {
        Promise.all([
            Str.get_string("enrol_users", "local_airpay_learningpath"),
            Str.get_string("confirm_unenrol_user", "local_airpay_learningpath", name),
            Str.get_string("delete", "core")
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], label = strings[2];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{
                    methodname: "local_airpay_learningpath_unenrol_user",
                    args: {pathid: pathid, userid: userid}
                }])[0].then(function() {
                    Notification.addNotification({message: "User unenrolled.", type: "success"});
                    refreshTable();
                    return null;
                }).catch(Notification.exception);
                return true;
            }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    // ── Click delegators ───────────────────────────────────────────────

    var handleIndexClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var pathid = parseInt(trigger.dataset.pathid || "0", 10);
        var name = trigger.dataset.name || "this path";
        switch (action) {
            case "create-path":   event.preventDefault(); openPathForm(0, trigger); break;
            case "edit-path":     event.preventDefault(); openPathForm(pathid, trigger); break;
            case "archive-path":  event.preventDefault(); confirmStatus(pathid, name, false, trigger); break;
            case "activate-path": event.preventDefault(); confirmStatus(pathid, name, true, trigger); break;
            case "delete-path":   event.preventDefault(); confirmDelete(pathid, name, trigger); break;
        }
    };

    var handleViewClick = function(pathid) {
        return function(event) {
            var trigger = event.target.closest("[data-action]");
            if (!trigger) return;
            var action = trigger.dataset.action;
            var courseid = parseInt(trigger.dataset.courseid || "0", 10);
            var userid = parseInt(trigger.dataset.userid || "0", 10);
            var name = trigger.dataset.name || "this item";
            switch (action) {
                case "add-courses":
                    event.preventDefault();
                    openAssignCoursesForm(pathid, trigger); break;
                case "enrol-users":
                    event.preventDefault();
                    openEnrolUsersForm(pathid, trigger); break;
                case "unassign-course":
                    event.preventDefault();
                    confirmUnassignCourse(pathid, courseid, name, trigger); break;
                case "unenrol-user":
                    event.preventDefault();
                    confirmUnenrolUser(pathid, userid, name, trigger); break;
            }
        };
    };

    return {
        init: function() {
            var root = document.querySelector("[data-region=\"airpay-learningpath\"]") || document.body;
            if (root.dataset.airpayLearningpathInit === "1") return;
            root.dataset.airpayLearningpathInit = "1";
            root.addEventListener("click", handleIndexClick);
        },
        initView: function(pathid) {
            var root = document.querySelector("[data-region=\"airpay-path-view\"]") || document.body;
            if (root.dataset.airpayPathviewInit === "1") return;
            root.dataset.airpayPathviewInit = "1";
            root.addEventListener("click", handleViewClick(pathid));
        }
    };
});
